/* tests/test_automode_diff.c -- automode.c against a frozen set of
 * reference traces.
 *
 * tests/golden/ *.expected is a one-time capture of the reference
 * behaviour for a fixed trace set (tests/golden/ *.trace), committed to
 * git. `meson test` runs THIS binary against tests/golden/, with no
 * external interpreter or network access involved at all -- see
 * tests/meson.build's own comment on the 'automode_diff' test.
 *
 * If automode.c's behaviour is EVER meant to change on purpose,
 * tests/golden/ *.expected must be regenerated by hand from whatever the
 * new intended behaviour is -- this is a frozen regression baseline, same
 * as any other golden-file test.
 *
 * Two modes:
 *   test_automode_diff <trace-file>       -- run ONE trace, print its
 *     output to stdout (a regen tool -- used to produce a fresh
 *     tests/golden/<name>.expected; also handy for
 *     manually inspecting one trace's decisions).
 *   test_automode_diff <golden-dir>       -- what `meson test` actually
 *     runs: every tests/golden/ *.trace against its *.expected sibling,
 *     byte-for-byte, no subprocess, no network -- exits
 *     non-zero (with a diff-like report) on the first mismatch or if fewer
 *     than 25 pairs are found (the differential suite's own "at least 25
 *     scenarios" requirement).
 */
#include <dirent.h>
#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>

#include "core/automode.h"

#define TRACE_OUT_CAP (32 * 1024)

static void format_actions(char *out, size_t out_len, const m4_automode_decision_t *d)
{
	if (d->action_count == 0) {
		snprintf(out, out_len, "NONE");
		return;
	}
	out[0] = '\0';
	for (size_t i = 0; i < d->action_count; i++) {
		if (i > 0)
			strncat(out, ",", out_len - strlen(out) - 1);
		strncat(out, m4_automode_action_name(d->actions[i]), out_len - strlen(out) - 1);
	}
}

/* Appends one line to `*used`/`out` (capacity `out_cap`), snprintf-style
 * (never overflows, silently truncates past out_cap -- for these traces
 * TRACE_OUT_CAP is generous enough that truncation would itself indicate a
 * bug/runaway trace, not a real need for a bigger buffer). */
__attribute__((format(printf, 4, 5)))
static void append_line(char *out, size_t out_cap, size_t *used, const char *fmt, ...)
{
	va_list ap;
	size_t off = *used < out_cap ? *used : out_cap;
	int n;

	va_start(ap, fmt);
	n = vsnprintf(out + off, out_cap - off, fmt, ap);
	va_end(ap);
	if (n > 0)
		*used += (size_t)n;
}

static void append_decision(char *out, size_t out_cap, size_t *used, const char *cmd,
			     const m4_automode_decision_t *d, const m4_automode_core_t *core, double now)
{
	char actions[96];
	m4_automode_status_t st;

	format_actions(actions, sizeof(actions), d);
	m4_automode_status(core, now, &st);
	append_line(out, out_cap, used,
		    "%s actions=%s frozen=%d call_active=%d call_reason=%s mic_active=%d hold_active=%d\n", cmd,
		    actions, st.frozen, st.call_active, st.call_active_reason, st.mic_active, st.hold_active);
}

/* Runs `trace_path` against core/automode.c,
 * appending one line per Decision-producing event to `out` (capacity
 * out_cap). Returns
 * 0 on success, -1 on a file/parse error (message on stderr). */
static int run_trace_file(const char *trace_path, char *out, size_t out_cap)
{
	FILE *f = fopen(trace_path, "r");
	m4_automode_core_t *core = NULL;
	char line[512];
	int lineno = 0;
	int rc = 0;
	size_t used = 0;

	out[0] = '\0';
	if (f == NULL) {
		fprintf(stderr, "%s: cannot open: %s\n", trace_path, strerror(errno));
		return -1;
	}

	while (fgets(line, sizeof(line), f) != NULL) {
		char *nl;
		char *p;
		char cmd[16] = { 0 };
		char a1[32] = { 0 }, a2[32] = { 0 }, a3[32] = { 0 }, a4[32] = { 0 };
		int matched;

		lineno++;
		nl = strchr(line, '\n');
		if (nl != NULL)
			*nl = '\0';

		p = line;
		while (*p == ' ' || *p == '\t')
			p++;
		if (*p == '\0' || *p == '#')
			continue;

		/* extra %n guards against a stray 6th token going unnoticed --
		 * every command in the grammar has at most 4 arguments. */
		matched = sscanf(p, "%15s %31s %31s %31s %31s", cmd, a1, a2, a3, a4);
		if (matched < 1) {
			fprintf(stderr, "%s:%d: empty/unparseable line\n", trace_path, lineno);
			rc = -1;
			break;
		}

		if (strcmp(cmd, "CONFIG") == 0) {
			m4_automode_config_t cfg;

			cfg.on_debounce_s = atof(a1);
			cfg.off_debounce_s = atof(a2);
			cfg.max_switches = atoi(a3);
			cfg.rate_window_s = atof(a4);
			if (core != NULL)
				m4_automode_free(core);
			core = m4_automode_new(&cfg);
			continue;
		}

		if (core == NULL)
			core = m4_automode_new(NULL);

		if (strcmp(cmd, "START") == 0) {
			double now = atof(a2);
			m4_automode_decision_t d = m4_automode_start(core, now, a1);

			append_decision(out, out_cap, &used, cmd, &d, core, now);
		} else if (strcmp(cmd, "MIC") == 0) {
			double now = atof(a2);
			m4_automode_decision_t d = m4_automode_on_mic_activity_changed(core, atoi(a1), now);

			append_decision(out, out_cap, &used, cmd, &d, core, now);
		} else if (strcmp(cmd, "HOLD") == 0) {
			double now = atof(a2);
			m4_automode_decision_t d = m4_automode_on_mic_hold_changed(core, atoi(a1), now);

			append_decision(out, out_cap, &used, cmd, &d, core, now);
		} else if (strcmp(cmd, "TICK") == 0) {
			double now = atof(a1);
			m4_automode_decision_t d = m4_automode_tick(core, now);

			append_decision(out, out_cap, &used, cmd, &d, core, now);
		} else if (strcmp(cmd, "EXTERNAL") == 0) {
			double now = atof(a2);
			m4_automode_decision_t d = m4_automode_note_external_call_state(core, a1, now);

			append_decision(out, out_cap, &used, cmd, &d, core, now);
		} else if (strcmp(cmd, "RESULT") == 0) {
			double now = atof(a3);
			m4_automode_action_t action =
				(strcmp(a1, "CALL_ON") == 0) ? M4_AUTOMODE_ACTION_CALL_ON : M4_AUTOMODE_ACTION_CALL_OFF;

			m4_automode_note_call_result(core, action, atoi(a2), now);
			/* no output line -- note_call_result() returns nothing. */
		} else if (strcmp(cmd, "RESUME") == 0) {
			double now = atof(a1);
			m4_automode_decision_t d = m4_automode_resume(core, now);

			append_decision(out, out_cap, &used, cmd, &d, core, now);
		} else {
			fprintf(stderr, "%s:%d: unknown command %s\n", trace_path, lineno, cmd);
			rc = -1;
			break;
		}
	}

	fclose(f);
	if (core != NULL)
		m4_automode_free(core);
	return rc;
}

/* --- dev/regen mode: print one trace's output to stdout ------------------- */

static int run_single_file_mode(const char *trace_path)
{
	static char out[TRACE_OUT_CAP];

	if (run_trace_file(trace_path, out, sizeof(out)) != 0)
		return 2;
	fputs(out, stdout);
	return 0;
}

/* --- golden-dir mode: what `meson test` runs ------------------------------- */

static int has_suffix(const char *s, const char *suffix)
{
	size_t ls = strlen(s), lsuf = strlen(suffix);

	return ls >= lsuf && strcmp(s + ls - lsuf, suffix) == 0;
}

static int run_golden_dir_mode(const char *dir_path)
{
	DIR *d = opendir(dir_path);
	struct dirent *ent;
	int n_pairs = 0;
	int n_fail = 0;
	static char actual[TRACE_OUT_CAP];
	static char expected[TRACE_OUT_CAP];

	if (d == NULL) {
		fprintf(stderr, "%s: %s\n", dir_path, strerror(errno));
		return 2;
	}

	while ((ent = readdir(d)) != NULL) {
		char trace_path[1024], expected_path[1024];
		FILE *ef;
		size_t exp_len;

		if (!has_suffix(ent->d_name, ".trace"))
			continue;
		n_pairs++;

		snprintf(trace_path, sizeof(trace_path), "%s/%s", dir_path, ent->d_name);
		snprintf(expected_path, sizeof(expected_path), "%s/%.*s.expected", dir_path,
			 (int)(strlen(ent->d_name) - 6) /* strip ".trace" */, ent->d_name);

		if (run_trace_file(trace_path, actual, sizeof(actual)) != 0) {
			fprintf(stderr, "FAIL %s: trace itself failed to run (see above)\n", ent->d_name);
			n_fail++;
			continue;
		}

		ef = fopen(expected_path, "r");
		if (ef == NULL) {
			fprintf(stderr, "FAIL %s: no matching golden file %s (%s)\n", ent->d_name, expected_path,
				strerror(errno));
			n_fail++;
			continue;
		}
		exp_len = fread(expected, 1, sizeof(expected) - 1, ef);
		expected[exp_len] = '\0';
		fclose(ef);

		if (strcmp(actual, expected) != 0) {
			fprintf(stderr, "FAIL %s: output differs from %s\n", ent->d_name, expected_path);
			fprintf(stderr, "--- expected (%s)\n%s", expected_path, expected);
			fprintf(stderr, "--- actual (core/automode.c)\n%s", actual);
			fprintf(stderr, "---\n");
			n_fail++;
		}
	}
	closedir(d);

	if (n_pairs < 25) {
		fprintf(stderr, "FAIL: only %d golden trace(s) in %s, need >=25\n", n_pairs, dir_path);
		n_fail++;
	}

	if (n_fail == 0)
		printf("OK: %d golden traces, core/automode.c matches the frozen baseline byte-for-byte\n", n_pairs);
	return n_fail == 0 ? 0 : 1;
}

int main(int argc, char **argv)
{
	struct stat st;

	if (argc != 2) {
		fprintf(stderr, "usage: %s <trace-file>          (dev/regen: print one trace's output)\n"
				 "       %s <golden-dir>          (meson test: compare every *.trace "
				 "against its *.expected)\n",
			argv[0], argv[0]);
		return 2;
	}
	if (stat(argv[1], &st) != 0) {
		fprintf(stderr, "%s: %s\n", argv[1], strerror(errno));
		return 2;
	}
	if (S_ISDIR(st.st_mode))
		return run_golden_dir_mode(argv[1]);
	return run_single_file_mode(argv[1]);
}
